/// 比較関数を受け取る優先度付きキュー
/// 標準ライブラリの BinaryHeap だと比較関数を受け取れないので自作
///
/// compare(a, b) が Ordering::Lessを返す → aが優先
///
/// |a, b| a.cmp(b) → 小さい順
/// |a, b| b.cmp(a) → 大きい順
pub struct PriorityQueue<T, F>
where
    T: Copy + Default,
    F: Fn(&T, &T) -> Ordering,
{
    /// ヒープ本体
    heap: Vec<T>,

    /// 現在の要素数
    n: usize,

    /// 比較関数
    /// compare(a, b) == Ordering::Lessならaが優先
    compare: F,
} // end of constructor

impl<T, F> PriorityQueue<T, F>
where
    T: Copy + Default,
    F: Fn(&T, &T) -> Ordering,
{
    /// 空の優先度付きキューを作成
    pub fn new(compare: F) -> Self {
        return Self::with_capacity(16, compare);
    } // end of method

    /// capacityを指定して優先度付きキューを作成
    /// heap[0]をダミーにするので +1個確保
    pub fn with_capacity(capacity: usize, compare: F) -> Self {
        let capacity: usize = capacity.max(1);
        return Self {
            heap: vec![T::default(); capacity + 1],
            n: 0,
            compare,
        };
    } // end of method

    /// 要素数を返す
    #[inline(always)]
    pub fn len(&self) -> usize {
        return self.n;
    } // end of method

    /// 空かどうかを返す
    pub fn is_empty(&self) -> bool {
        return self.n == 0;
    } // end of method

    /// 先頭の要素を読み取り
    #[inline(always)]
    pub fn peek(&self) -> Option<&T> {
        if self.n == 0 {
            return None;
        }

        return Some(&self.heap[1]);
    } // end of method

    /// 要素を追加
    #[inline(always)]
    pub fn push(&mut self, value: T) {
        // 1-indexedなので次に使う場所はn+1
        // 配列長が足りないときは二倍に拡張
        if self.n + 1 >= self.heap.len() {
            self.heap.resize(self.heap.len() << 1, T::default());
        }

        self.n += 1;
        let mut index: usize = self.n;

        // valueを入れる場所を探して親を下にずらしていく
        while index > 1 {
            let parent: usize = index >> 1;

            // parentがvalue以上の優先度なら終了
            if (self.compare)(&self.heap[parent], &value) != Ordering::Greater {
                break;
            }

            // 親を子にずらす
            self.heap[index] = self.heap[parent];
            index = parent;
        }

        // 最後に空いた場所へvalueを挿入
        self.heap[index] = value;
    } // end of method

    /// 先頭の要素を取り出す
    #[inline(always)]
    pub fn pop(&mut self) -> Option<T> {
        if self.n == 0 {
            return None;
        }

        // 返す値
        let answer: T = self.heap[1];

        // 一番後ろの値を取り出して、適切な場所へ降ろしていく
        let last: T = self.heap[self.n];
        self.n -= 1;

        // 要素が1個だけだった場合はanswerを返して終了
        if self.n == 0 {
            return Some(answer);
        }

        let mut index: usize = 1;
        // lastを入れる場所まで降ろしていく
        while (index << 1) <= self.n {
            let left: usize = index << 1;
            let right = left | 1;

            // 左右の子で優先度が高い方
            let mut child: usize = left;
            if right <= self.n && (self.compare)(&self.heap[right], &self.heap[left]) == Ordering::Less {
                child = right;
            }

            // lastがchildより優先or同じならそこに入れるのでストップ
            if (self.compare)(&last, &self.heap[child]) != Ordering::Greater {
                break;
            }

            // 優先度の高い子を親の位置へ上げる
            self.heap[index] = self.heap[child];
            index = child;
        }

        // 最後に空いた位置へlastを入れる
        self.heap[index] = last;
        return Some(answer);
    } // end of method
} // end of impl PriorityQueue

/// Orderingを持つ型, デフォルトの優先度に基づく優先度付きキュー
/// 数値型なら大きい順
/// 標準ライブラリのBinaryHeapに近い
pub struct OrdPriorityQueue<T>
where
    T: Copy + Default + Ord,
{
    /// 自作PriorityQueueをもたせる
    /// 比較関数を関数ポインタとして固定
    pq: PriorityQueue<T, fn(&T, &T) -> Ordering>,
} // end of struct

impl<T> OrdPriorityQueue<T>
where
    T: Copy + Default + Ord,
{
    /// 空の優先度付きキュー作成
    /// 大きい順
    pub fn new() -> Self {
        return Self::new_max();
    } // end of constructor

    /// 空の優先度付きキュー作成
    /// 大きい順
    pub fn new_max() -> Self {
        return Self::with_capacity_max(16);
    } // end of constructor

    /// 空の優先度付きキュー作成
    /// 小さい順
    pub fn new_min() -> Self {
        return Self::with_capacity_min(16);
    } // end of constructor

    /// capacityを指定して優先度付きキュー作成
    /// 大きい順
    pub fn with_capacity(capacity: usize) -> Self {
        return Self::with_capacity_max(capacity);
    } // end of constructor

    /// capacityを指定して優先度付きキュー作成
    /// 大きい順
    pub fn with_capacity_max(capacity: usize) -> Self {
        return Self {
            pq: PriorityQueue::with_capacity(capacity, ord_max_compare::<T>),
        };
    } // end of constructor

    /// capacityを指定して優先度付きキュー作成
    /// 小さい順
    pub fn with_capacity_min(capacity: usize) -> Self {
        return Self {
            pq: PriorityQueue::with_capacity(capacity, ord_min_compare::<T>),
        };
    } // end of constructor

    /// 要素数を返す
    #[inline(always)]
    pub fn len(&self) -> usize {
        return self.pq.len();
    } // end of method

    /// 空かどうかを返す
    #[inline(always)]
    pub fn is_empty(&self) -> bool {
        return self.pq.is_empty();
    } // end of method

    /// 先頭の要素を読み取り
    #[inline(always)]
    pub fn peek(&self) -> Option<&T> {
        return self.pq.peek();
    } // end of method

    /// 要素を追加
    #[inline(always)]
    pub fn push(&mut self, value: T) {
        self.pq.push(value);
    } // end of method

    /// 先頭の要素を取り出す
    #[inline(always)]
    pub fn pop(&mut self) -> Option<T> {
        return self.pq.pop();
    } // end of method
} // end of impl<T> OrdPriorityQueue<T>

impl<T> Default for OrdPriorityQueue<T>
where
    T: Copy + Default + Ord,
{
    /// デフォルトの優先度付きキューを作成
    ///
    /// OrdPriorityQueue::new() と同じ挙動にする
    /// つまり、大きい値から取り出す
    fn default() -> Self {
        return Self::new();
    } // end of method
} // end of impl Default

/// 大きい値を優先する比較関数
///
/// compare(a, b) が Ordering::Less を返すと a が優先
/// b.cmp(a) にすると大きい値が優先される
#[inline(always)]
fn ord_max_compare<T>(a: &T, b: &T) -> Ordering
where
    T: Ord,
{
    return b.cmp(a);
} // end of function

/// 小さい値を優先する比較関数
///
/// compare(a, b) が Ordering::Less を返すと a が優先
/// a.cmp(b) にすると小さい値が優先される
#[inline(always)]
fn ord_min_compare<T>(a: &T, b: &T) -> Ordering
where
    T: Ord,
{
    return a.cmp(b);
} // end of function
